import { char, integer, numeric, timestamp, uuid } from "drizzle-orm/pg-core";

/**
 * Shared column builders. Conventions (core-ports.md §1, §8):
 * - ids are UUIDv7 generated by the application, so no database default;
 * - instants are `timestamptz`, calendar dates (Europe/Prague) are `date`;
 * - BigDecimal values are `numeric` read and written as decimal strings; money totals use scale 2;
 * - `revision` is the optimistic concurrency counter (rule S2), starting at 1.
 */

export const id = () => uuid("id").primaryKey();

export const workspaceIdColumn = () => uuid("workspace_id").notNull();

export const instant = (name: string) => timestamp(name, { withTimezone: true, mode: "string" });

export const createdAt = () => instant("created_at").defaultNow().notNull();

export const updatedAt = () => instant("updated_at").defaultNow().notNull();

export const revision = () => integer("revision").notNull().default(1);

/** ISO 4217 code, `^[A-Z]{3}$` (core-ports.md:79). */
export const currency = (name: string) => char(name, { length: 3 });

/** Money amount in the row's currency, two decimal places. */
export const money = (name: string) => numeric(name, { precision: 18, scale: 2, mode: "string" });

/** Unbounded BigDecimal (quantities, unit prices, FX rates). */
export const decimal = (name: string) => numeric(name, { mode: "string" });
